package com.servicedesk360.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="audit_logs") public class AuditLog{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="tenant_id",nullable=false) Long tenantId; @Column(name="actor_user_id",nullable=false) Long actorUserId; @Column(nullable=false,length=80) String action; @Column(name="target_type",nullable=false,length=80) String targetType; @Column(name="target_id") Long targetId; @Column(name="details_json",columnDefinition="text") String detailsJson; @Column(name="created_at",nullable=false,updatable=false) Instant createdAt; protected AuditLog(){} public AuditLog(Long t,Long a,String ac,String tt,Long ti,String d){tenantId=t;actorUserId=a;action=ac;targetType=tt;targetId=ti;detailsJson=d;} @PrePersist void create(){createdAt=Instant.now();} public Long getId(){return id;} public Long getTenantId(){return tenantId;} public Long getActorUserId(){return actorUserId;} public String getAction(){return action;} public String getTargetType(){return targetType;} public Long getTargetId(){return targetId;} public String getDetailsJson(){return detailsJson;} public Instant getCreatedAt(){return createdAt;} }
